INSERT IGNORE INTO categories (id, title, description, image_url) VALUES
(1, 'Cabañas', 'Madera, chimenea y montaña: refugios para desconectarse.', 'https://images.unsplash.com/photo-1706151912645-d61f4c391cdf?w=1400&q=80&auto=format&fit=crop'),
(2, 'Glamping', 'Domos, burbujas y carpas con cama de verdad bajo las estrellas.', 'https://images.unsplash.com/photo-1641569618527-68e26db76db0?w=1400&q=80&auto=format&fit=crop'),
(3, 'Hoteles boutique', 'Casas con historia, pocas habitaciones y trato cercano.', 'https://images.unsplash.com/photo-1680579178966-8019436998e7?w=1400&q=80&auto=format&fit=crop'),
(4, 'Fincas', 'Casas de campo con espacio para la familia, piscina y cafetales.', 'https://images.unsplash.com/photo-1693357635675-95cc79c6ef46?w=1400&q=80&auto=format&fit=crop'),
(5, 'Apartamentos', 'Tu casa en la ciudad: cocina, sala y wifi para quedarse más días.', 'https://images.unsplash.com/photo-1564078516393-cf04bd966897?w=1400&q=80&auto=format&fit=crop'),
(6, 'Hostales', 'Camas cómodas, zonas comunes y viajeros de todo el mundo.', 'https://images.unsplash.com/photo-1619810230359-b2c2f61c49cd?w=1400&q=80&auto=format&fit=crop');
INSERT IGNORE INTO products (id, name, description, city, address, price_per_night, category_id, created_at) VALUES
(1, 'Cabaña El Mirador del Cocora', 'Cabaña de madera para cuatro personas frente a las palmas de cera del valle de Cocora. Chimenea, terraza con hamacas y desayuno campesino incluido. A diez minutos en jeep del pueblo.', 'Salento, Quindío', 'Vereda Cocora, km 4', 380000, 1, NOW()),
(2, 'Cabaña Niebla de Guatavita', 'Refugio de montaña a una hora de Bogotá, con vista al embalse de Tominé. Sala con chimenea, cocina equipada y senderos privados entre frailejones.', 'Guatavita, Cundinamarca', 'Vereda Potrero Largo', 320000, 1, NOW()),
(3, 'Refugio Alto de Minca', 'Cabaña de guadua abierta a la Sierra Nevada, con cama doble, mosquitero y fogata al atardecer. Cascadas y fincas de cacao a pocos minutos caminando.', 'Minca, Magdalena', 'Vía Minca - El Campano, km 6', 290000, 1, NOW()),
(4, 'Cabaña Laguna del Peñol', 'Cabaña blanca con muelle propio sobre el embalse de Guatapé y vista a la Piedra del Peñol. Kayaks incluidos y sala con chimenea para las noches frescas.', 'Guatapé, Antioquia', 'Vereda La Piedra, sector embalse', 350000, 1, NOW()),
(5, 'Domo Cielo de Barichara', 'Domo geodésico con techo transparente para dormir mirando las estrellas del cañón del Chicamocha. Jacuzzi exterior, desayuno santandereano y luces cálidas en la terraza.', 'Barichara, Santander', 'Camino Real a Guane, km 2', 410000, 2, NOW()),
(6, 'Glamping Burbuja del Bosque', 'Burbuja transparente sobre una plataforma de madera en medio del bosque andino. Cama king, calefacción y vista a las luces de Bogotá al anochecer.', 'La Calera, Cundinamarca', 'Vía La Calera - Sopó, km 9', 450000, 2, NOW()),
(7, 'Glamping Carpa Río Claro', 'Carpa safari junto al cañón del Río Claro, con cama doble, baño privado y sala exterior. Rafting, cavernas y piscinas naturales de mármol a pocos pasos.', 'San Luis, Antioquia', 'Autopista Medellín - Bogotá, km 152', 260000, 2, NOW()),
(8, 'Glamping Bosque de Niebla', 'Cabaña en A entre pinos y niebla, a 40 minutos de Medellín. Fogata con sillas, mesa para comer afuera y ruta de silleteros para caminar en la mañana.', 'Santa Elena, Antioquia', 'Vereda Mazo, km 3', 340000, 2, NOW()),
(9, 'Hotel Casa Balcones', 'Casa colonial restaurada dentro de la ciudad amurallada, con ocho habitaciones, patio con fuente y balcones llenos de buganvilias. A dos cuadras de la Plaza de Santo Domingo.', 'Cartagena, Bolívar', 'Calle del Cuartel 36-12, Centro Histórico', 690000, 3, NOW()),
(10, 'Hotel Claustro de Leyva', 'Casona de muros blancos y puertas de madera a una cuadra de la plaza mayor. Habitaciones con techo de vigas, patio de piedra y desayuno boyacense.', 'Villa de Leyva, Boyacá', 'Carrera 9 # 13-25', 420000, 3, NOW()),
(11, 'Hotel Bahía Taganga', 'Hotel pequeño frente a la bahía de Taganga, con piscina entre palmeras y terraza para ver el atardecer sobre el Caribe. Salidas de buceo desde la playa.', 'Santa Marta, Magdalena', 'Carrera 1 # 18-40, Taganga', 380000, 3, NOW()),
(12, 'Hotel Plaza de Salento', 'Casa de bahareque pintada de colores sobre la Calle Real. Habitaciones con escritorio, café de origen en cada piso y el mirador a cinco minutos.', 'Salento, Quindío', 'Calle Real # 4-15', 310000, 3, NOW()),
(13, 'Finca Cafetera La Esperanza', 'Finca cafetera en producción con casa para diez personas. Recorrido por el cafetal, cosecha y tostión con la familia que la trabaja desde hace tres generaciones.', 'Montenegro, Quindío', 'Vereda Pueblo Tapao', 520000, 4, NOW()),
(14, 'Finca Villa Palmeras', 'Casa de clima cálido para doce personas con piscina, kiosco con asador y prados para los niños. A dos horas de Bogotá, ideal para puentes festivos.', 'Anapoima, Cundinamarca', 'Vereda San Antonio, lote 7', 750000, 4, NOW()),
(15, 'Finca La Arriería', 'Casa campesina de puertas rojas entre potreros y montaña, con caballos para recorrer los caminos de herradura. Ocho huéspedes, cocina de leña y huerta.', 'Jardín, Antioquia', 'Vereda La Linda', 430000, 4, NOW()),
(16, 'Finca Palmas del Quindío', 'Finca en lo alto de la cordillera con vista a los valles de palma y guadua. Seis habitaciones, corredores con hamacas y café recién cosechado en la mañana.', 'Filandia, Quindío', 'Vereda Cruces', 480000, 4, NOW()),
(17, 'Apartamento Laureles Verde', 'Apartamento de dos habitaciones en el barrio Laureles, a pasos de cafés y del metro. Cocina completa, escritorio para trabajar y balcón con plantas.', 'Medellín, Antioquia', 'Circular 1 # 70-12, Laureles', 240000, 5, NOW()),
(18, 'Apartamento Mar de Bocagrande', 'Apartamento con ventanales al mar en Bocagrande, sala amplia, dos habitaciones y piscina en el edificio. La playa queda cruzando la avenida.', 'Cartagena, Bolívar', 'Avenida San Martín # 6-45, Bocagrande', 410000, 5, NOW()),
(19, 'Hostal La Candelaria', 'Hostal en una casa colonial del centro histórico, con habitaciones compartidas y privadas, biblioteca y terraza. Caminando al Museo del Oro y a Monserrate.', 'Bogotá, D. C.', 'Calle 12C # 2-36, La Candelaria', 75000, 6, NOW()),
(20, 'Hostal Colores de Guatapé', 'Hostal entre las calles de zócalos pintados de Guatapé. Dormitorios con luz natural, patio con murales y salida diaria a la Piedra del Peñol.', 'Guatapé, Antioquia', 'Calle 31 # 28-10', 68000, 6, NOW());
